/bin/bash -lc "cat > /tmp/rust_fmt_probe.rs <<'RS'
const PRECISION: usize = 6;

fn trim_trailing_zeros(mut s: String) -> String {
    if let Some(dot_index) = s.find('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.len() == dot_index + 1 {
            s.pop();
        }
    }
    s
}

fn scientific_to_fixed(digits: &str, exponent: i32) -> String {
    let point = exponent + 1;
    let mut result = String::new();
    if point <= 0 {
        result.push_str(\"0.\");
        for _ in 0..usize::try_from(-point).unwrap() {
            result.push('0');
        }
        result.push_str(digits);
    } else {
        let point = usize::try_from(point).unwrap();
        if point >= digits.len() {
            result.push_str(digits);
            for _ in 0..(point - digits.len()) {
                result.push('0');
            }
        } else {
            result.push_str(&digits[..point]);
            result.push('.');
            result.push_str(&digits[point..]);
        }
    }
    trim_trailing_zeros(result)
}

fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() { \"-nan\".into() } else { \"nan\".into() };
    }
    if value.is_infinite() {
        return if value.is_sign_negative() { \"-inf\".into() } else { \"inf\".into() };
    }
    if value == 0.0 {
        return if value.is_sign_negative() { \"-0\".into() } else { \"0\".into() };
    }

    let negative = value.is_sign_negative();
    let scientific = format"'!("{:.*e}", PRECISION - 1, f64::from(value.abs()));
    let (mantissa_raw, exponent_raw) = scientific.split_once('"'e').unwrap();
    let exponent: i32 = exponent_raw.parse().unwrap();

    if exponent < -4 || exponent >= PRECISION as i32 {
        let mantissa = trim_trailing_zeros(mantissa_raw.to_string());
        let mut out = String::new();
        if negative { out.push('-'); }
        out.push_str(&mantissa);
        out.push('e');
        out.push(if exponent < 0 { '-' } else { '+' });
        let exponent_abs = exponent.abs();
        if exponent_abs < 10 {
            out.push('0');
        }
        out.push_str(&exponent_abs.to_string());
        return out;
    }

    let digits: String = mantissa_raw.chars().filter(|&ch| ch "'!= '"'.').collect();
    let mut out = scientific_to_fixed(&digits, exponent);
    if negative {
        out.insert(0, '-');
    }
    out
}

fn main() {
    let vals: [f32; 12] = [
        0.0,
        -0.0,
        0.45,
        3.5762787e-7,
        999999.5,
        999999.4,
        0.00009999995,
        0.00009999994,
        f32::INFINITY,
        f32::NEG_INFINITY,
        f32::NAN,
        -f32::NAN,
    ];
    for v in vals {
        println"'!("[{}]", format_cpp_float(v));
    }
}
